(* [comment removed for export] *)
Definition art_gs_ia {FSG : Type} (G : art_gs FSG) : art_gs FSG :=
  GS FSG (g_log FSG G) (g_inited FSG G) (g_cls FSG G) (g_st FSG G) (g_sec FSG G) (g_sec_committed FSG G) (g_qt FSG G) (g_qg FSG G) (g_depot FSG G) true (g_fs FSG G).
Definition art_ia_zone (z : Z) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$z;R+0!2+1!2+2!2'3!1,4|D6e9c0;#1!2'5#1!1,4|Def9f0;!2+2!2'3!1,4|Dfd248;#1!2'5#1!1,4|Dfd24c;").

Section FrameLawX.
Variable FSG : Type.
Variables MAPS0 RESV0 : list (word * word).
Variables (rn : art_run) (G : art_gs FSG) (LB : list (Z * Z)) (M M' : word -> option byte).
Hypothesis REP : art_alloc_rep FSG rn G LB M.
Hypothesis GRW : mem_grows M M'.
Variable EX : Z -> Prop.
Hypothesis HEX : forall z, EX z -> art_ia_zone z.
Let XB (z : Z) : Prop := in_block LB z \/ EX z.
Hypothesis AG : forall x : word, art_alloc_zone FSG rn G (U x) -> ~ XB (U x) -> M' x = M x.
